use std::future::Future;
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
struct NoopWake;
impl Wake for NoopWake { fn wake(self: Arc<Self>) {} }
fn run_ready<F: Future>(future: F) -> F::Output {
    let waker = Waker::from(Arc::new(NoopWake));
    let mut context = Context::from_waker(&waker);
    let mut future = Box::pin(future);
    match future.as_mut().poll(&mut context) {
        Poll::Ready(value) => value,
        Poll::Pending => panic!("this tiny example only handles immediately-ready futures"),
    }
}
async fn answer() -> u8 { 42 }
fn main() { println!("{}", run_ready(answer())); }

#[tokio::main]
async fn main() {
    async fn read_sensor(name: &str, delay_ms: u64) -> String {
        tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
        format!("{name}:ready")
    }
    let (temperature, humidity) = tokio::join!(
        read_sensor("temperature", 5),
        read_sensor("humidity", 3),
    );
    println!("{temperature}\n{humidity}");
}
